// Get the current item's JSON
const item = $input.item.json;

// Check multiple possible paths where the AI text could be stored
let rawText = null;

if (item.response?.generations?.[0]?.[0]?.text) {
    rawText = item.response.generations[0][0].text;
} else if (item.text) {
    rawText = item.text;
} else if (item.output) {
    rawText = item.output;
} else {
    // If it's stored somewhere else, look for it or stringify for debugging
    rawText = typeof item === 'string' ? item : JSON.stringify(item);
}

// Clean up markdown block formatting if the AI added ```json ... ```
if (typeof rawText === 'string') {
    rawText = rawText.replace(/```json/g, "").replace(/```/g, "").trim();
}

// Parse into a clean JSON object
return JSON.parse(rawText);
